<?php

namespace Jankx\Gutenberg\Blocks;

use Jankx\Gutenberg\Block;

/**
 * Social Sharing Block
 *
 * Hiển thị các nút chia sẻ mạng xã hội sử dụng vanilla-sharing
 *
 * @package Jankx\Gutenberg\Blocks
 * @since 2.0.0
 */
class SocialSharingBlock extends Block
{
    protected $blockId = 'jankx/social-sharing';

    /**
     * Render callback for the block
     *
     * @param array $attributes Block attributes
     * @param string $content Block content
     * @return string Rendered HTML
     */
    public function render($attributes = [], $content = '')
    {
        // Get current post data
        global $post;

        $url = is_singular() ? get_permalink() : home_url();
        $title = is_singular() ? get_the_title() : get_bloginfo('name');

        // Get attributes with defaults
        $networks = $attributes['networks'] ?? ['facebook', 'twitter', 'linkedin', 'whatsapp', 'telegram'];
        $icon_size = $attributes['iconSize'] ?? 'medium';
        $show_labels = $attributes['showLabels'] ?? true;
        $style = $attributes['style'] ?? 'default';
        $alignment = $attributes['alignment'] ?? 'left';

        // Network labels
        $network_labels = apply_filters('jankx/social-sharing/network-labels', [
            'facebook' => __('Facebook', 'jankx'),
            'twitter' => __('Twitter', 'jankx'),
            'linkedin' => __('LinkedIn', 'jankx'),
            'whatsapp' => __('WhatsApp', 'jankx'),
            'telegram' => __('Telegram', 'jankx'),
            'pinterest' => __('Pinterest', 'jankx'),
            'reddit' => __('Reddit', 'jankx'),
            'email' => __('Email', 'jankx'),
            'copy' => __('Copy Link', 'jankx'),
            'messenger' => __('Messenger', 'jankx'),
            'viber' => __('Viber', 'jankx'),
            'line' => __('Line', 'jankx'),
        ]);

        // Network icons (SVG)
        $network_icons = $this->getNetworkIcons();

        // Build HTML
        ob_start();
        ?>
        <div class="wp-block-jankx-social-sharing alignment-<?php echo esc_attr($alignment); ?> style-<?php echo esc_attr($style); ?> size-<?php echo esc_attr($icon_size); ?>">
            <?php if (!empty($networks)): ?>
                <div class="sharing-title">
                    <strong><?php _e('Chia sẻ:', 'jankx'); ?></strong>
                </div>
                <div class="sharing-buttons">
                    <?php foreach ($networks as $network): ?>
                        <button
                            class="sharing-button <?php echo esc_attr($network); ?>"
                            data-network="<?php echo esc_attr($network); ?>"
                            data-url="<?php echo esc_url($url); ?>"
                            data-title="<?php echo esc_attr($title); ?>"
                            aria-label="<?php echo esc_attr(sprintf(__('Chia sẻ trên %s', 'jankx'), $network_labels[$network] ?? $network)); ?>"
                        >
                            <span class="sharing-icon">
                                <?php echo $network_icons[$network] ?? $network[0]; ?>
                            </span>
                            <?php if ($show_labels): ?>
                                <span class="sharing-label">
                                    <?php echo esc_html($network_labels[$network] ?? ucfirst($network)); ?>
                                </span>
                            <?php endif; ?>
                        </button>
                    <?php endforeach; ?>
                </div>
            <?php endif; ?>
        </div>
        <?php
        return ob_get_clean();
    }

